// Writes public/_redirects (Netlify syntax) from src/content/redirects.json.
// Run by `npm run build` before vite, so the file never drifts from the map.
import { readFileSync, writeFileSync } from 'node:fs'

const map = JSON.parse(readFileSync(new URL('../src/content/redirects.json', import.meta.url)))

const lines = [
  '# Generated by scripts/build-redirects.mjs — edit src/content/redirects.json instead.',
  '',
  '# WordPress ?p= and ?page_id= links (Netlify matches query params; see TODO for other hosts).',
]
for (const [id, to] of Object.entries(map.ids)) {
  lines.push(`/ p=${id} ${to} 301!`, `/ page_id=${id} ${to} 301!`)
}
lines.push('', '# WordPress pretty permalinks, feeds and uploads.')
for (const { from, to } of map.paths) lines.push(`${from} ${to} 301`)
lines.push(
  '/feed /noticias 301',
  '/feed/* /noticias 301',
  '/comments/feed /noticias 301',
  '/category/*/feed /noticias 301',
  '',
  '# SPA fallback — must stay last so it never shadows the rules above.',
  '/* /index.html 200',
  '',
)

writeFileSync(new URL('../public/_redirects', import.meta.url), lines.join('\n'))
